@staticmethod
def _copy_attribution(record: dict[str, object]) -> dict[str, object]:
    """Deep-copy a ``key, fork, left, right`` attribution dict.

    The copied result shares no tuples or dicts with the source, so it
    stays detached from the per-call attributions and internal state.
    """
    def copy_side(side: dict[str, object]) -> dict[str, object]:
        return {
            "value": side["value"],
            "cause": side["cause"],
            "path": tuple(side["path"]),  # type: ignore[arg-type]
            "affected": tuple(side["affected"]),  # type: ignore[arg-type]
        }

    return {
        "key": record["key"],
        "fork": record["fork"],
        "left": copy_side(record["left"]),  # type: ignore[arg-type]
        "right": copy_side(record["right"]),  # type: ignore[arg-type]
    }

